/* Renders everything from DATA (generated by study/build_page_data.py). No typed numbers. */
(function(){
"use strict";
const $ = s => document.querySelector(s);
const MODELS = DATA.models, ML = DATA.model_labels, TYPES = DATA.types, TL = DATA.type_labels;
const pct = (ok, n) => n ? Math.round(100*ok/n) : 0;
const cell = (m, c, t) => (DATA.table[m+"|"+c] || {})[t] || [0, 0];

/* ---------- headline numbers ---------- */
const bestModel = MODELS.map(m => [m, pct(...cell(m,"unaided","ALL"))]).sort((a,b)=>b[1]-a[1])[0];
const agentBest = MODELS.map(m => [m, pct(...cell(m,"agent","ALL"))]).sort((a,b)=>b[1]-a[1])[0];
let sureWrongTot = 0, sureTot = 0;
for (const m of MODELS){ const h = DATA.honesty[m]; if (h){ sureWrongTot += h.claimed_yes_wrong; sureTot += h.claimed_yes; } }
const maxClaim = MODELS.filter(m=>DATA.honesty[m]).sort((a,b)=>DATA.honesty[b].claimed_yes-DATA.honesty[a].claimed_yes)[0];
const minClaim = MODELS.filter(m=>DATA.honesty[m]).sort((a,b)=>DATA.honesty[a].claimed_yes-DATA.honesty[b].claimed_yes)[0];
const hcMax = DATA.honesty[maxClaim], hcMin = DATA.honesty[minClaim];
const agentDelta = pct(...cell(agentBest[0],"agent","ALL")) - pct(...cell(agentBest[0],"unaided","ALL"));
$("#hl1").textContent = `No. The best of the five answers ${pct(...cell(bestModel[0],"unaided","ALL"))} percent of the 120 tasks exactly right (${ML[bestModel[0]]}), the two-way kinds sit at coin-flip level, and expanding a phylo2vec vector is zero for every model.`;
$("#hl2").textContent = `No, in both directions. ${ML[maxClaim]} said "yes, I can" on ${hcMax.claimed_yes} of 120 and was wrong on ${hcMax.claimed_yes_wrong} of those; ${ML[minClaim]} said yes only ${hcMin.claimed_yes} times while actually answering ${pct(...cell(minClaim,"probe","ALL"))} percent right.`;
$("#hl3").textContent = `Only as far as the model can drive it. ${ML[agentBest[0]]} gains ${agentDelta > 0 ? "+" + agentDelta : agentDelta} points to ${pct(...cell(agentBest[0],"agent","ALL"))} percent with the library in hand; the new bottleneck is the tool call itself, and the page measures a remedy for that too.`;

/* ---------- domain figure: one 5-leaf tree, drawn + newick + vector ---------- */
(function(){
  const nw = "((A,(B,C)),(D,E));", vec = "0,1,0,3";
  $("#domain-nw").textContent = nw; $("#domain-vec").textContent = "[" + vec + "]";
  const svg = $("#domainfig");
  // hand-laid tiny tree; leaves at x by order A B C D E
  const leaves = {A:20, B:75, C:130, D:200, E:255};
  const y0 = 118, seg = [
    // [x1,y1,x2,y2]
    [leaves.B, y0, leaves.B, 88],[leaves.C, y0, leaves.C, 88],[leaves.B, 88, leaves.C, 88], // (B,C)
    [102, 88, 102, 58],[leaves.A, y0, leaves.A, 58],[leaves.A, 58, 102, 58],               // (A,(B,C))
    [61, 58, 61, 28],[leaves.D, y0, leaves.D, 88],[leaves.E, y0, leaves.E, 88],
    [leaves.D, 88, leaves.E, 88],[227, 88, 227, 28],[61, 28, 227, 28]
  ];
  svg.innerHTML = seg.map(s=>`<line x1="${s[0]}" y1="${s[1]}" x2="${s[2]}" y2="${s[3]}" stroke="#2c4a6b" stroke-width="2"/>`).join("") +
    Object.entries(leaves).map(([l,x])=>`<text x="${x}" y="${y0+18}" text-anchor="middle">${l}</text>`).join("");
})();

/* ---------- act 1: task browser ---------- */
const tasksByType = {};
for (const t of TYPES) tasksByType[t] = DATA.tasks.filter(x => x.type === t);
let curType = TYPES[0], curIdx = 0;
function renderChips(){
  $("#typechips").innerHTML = TYPES.map(t =>
    `<button class="chip ${t===curType?'on':''}" data-t="${t}">${TL[t]}</button>`).join("");
  document.querySelectorAll("#typechips .chip").forEach(b =>
    b.onclick = () => { curType = b.dataset.t; curIdx = 0; renderTask(); });
}
function renderTask(){
  renderChips();
  const list = tasksByType[curType], task = list[curIdx];
  $("#qtext").textContent = task.q;
  $("#qtruth").textContent = task.truth;
  $("#qpos").textContent = `task ${curIdx+1} of ${list.length} · ${TL[curType]}`;
  $("#qanswers").innerHTML = MODELS.map(m => {
    const e = task.runs[m+"|unaided"] || {pred:"(not run)", ok:false};
    const shown = e.pred === "" ? "(no parseable answer)" : e.pred;
    return `<tr><td>${ML[m]}</td><td class="mono">${escapeHtml(shown)}</td>
      <td class="num ${e.ok?'ok':'bad'}">${e.ok?'right':'wrong'}</td></tr>`;
  }).join("");
}
function escapeHtml(s){ return (s||"").replace(/[&<>]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;"}[c])); }
$("#prevq").onclick = () => { curIdx = (curIdx - 1 + tasksByType[curType].length) % tasksByType[curType].length; renderTask(); };
$("#nextq").onclick = () => { curIdx = (curIdx + 1) % tasksByType[curType].length; renderTask(); };
renderTask();

/* ---------- chart 1: small multiples, unaided accuracy by kind ---------- */
(function(){
  const SHORT = {qwen3b:"Qwen 3B", llama3b:"Llama 3B", gemma4b:"Gemma 4B", llama1b:"Llama 1B", mimir:"Mimir 1B"};
  const panelW = 205, panelH = 150, labW = 88, barH = 14, gap = 8;
  let html = `<svg width="${panelW*TYPES.length}" height="${panelH+30}" viewBox="0 0 ${panelW*TYPES.length} ${panelH+30}">`;
  TYPES.forEach((t, ti) => {
    const x0 = ti*panelW;
    html += `<text x="${x0+labW}" y="14" class="dim">${TL[t]}</text>`;
    const binary = (t === "closer" || t === "clade" || t === "same_topology");
    MODELS.forEach((m, mi) => {
      const [ok, n] = cell(m, "unaided", t);
      const p = n ? ok/n : 0, y = 26 + mi*(barH+gap);
      const w = Math.max(1, Math.round(p*100));
      html += `<text x="${x0+labW-6}" y="${y+11}" text-anchor="end" class="dim">${SHORT[m]||ML[m]}</text>`;
      html += `<rect x="${x0+labW}" y="${y}" width="100" height="${barH}" fill="#f3f1ed"/>`;
      html += `<rect x="${x0+labW}" y="${y}" width="${w}" height="${barH}" fill="#2c4a6b"/>`;
      html += `<text x="${x0+labW+104}" y="${y+11}">${pct(ok,n)}%</text>`;
    });
    if (binary){
      const gy1 = 22, gy2 = 26 + MODELS.length*(barH+gap) - gap + 4;
      html += `<line x1="${x0+labW+50}" y1="${gy1}" x2="${x0+labW+50}" y2="${gy2}" stroke="#b03a3a" stroke-dasharray="4 3"/>`;
      if (t === "closer") html += `<text x="${x0+labW+50}" y="${gy2+14}" text-anchor="middle" fill="#b03a3a">guess = 50</text>`;
    }
    html += `<text x="${x0+labW}" y="${panelH+22}" class="axis">0</text><text x="${x0+labW+100}" y="${panelH+22}" text-anchor="end" class="axis">100</text>`;
  });
  html += "</svg>";
  $("#chart1").innerHTML = html;
  const best = bestModel;
  const counting = Math.max(...MODELS.map(m => pct(...cell(m,"unaided","leaf_count"))));
  const p2vBest = Math.max(...MODELS.map(m => pct(...cell(m,"unaided","p2v"))));
  $("#cap1-take").textContent = `the three middle kinds are two-way choices, so the dashed line at 50 percent is what guessing earns; no model clears it by much, counting taxa tops out at ${counting} percent, and the vector kind is ${p2vBest} percent for everyone.`;
  $("#verdict1").innerHTML = `<b>Unaided, the models are close to guessing.</b>
    The best overall score is ${best[1]} percent (${ML[best[0]]}), and on the two-way kinds every model sits near the 50 percent a coin would earn.
    Counting taxa, the simplest task on the page, tops out at ${counting} percent; expanding a phylo2vec vector is ${p2vBest} percent for all five.
    Every answer behind these bars is in the task browser above, and the wrong ones are confidently, specifically wrong.`;
})();

/* ---------- act 2: honesty dumbbells + table + examples ---------- */
(function(){
  const W = 560, rowH = 40, labW = 110, axW = 380;
  let html = `<svg width="${W}" height="${MODELS.length*rowH+46}" viewBox="0 0 ${W} ${MODELS.length*rowH+46}">`;
  html += `<text x="${labW}" y="12" class="axis">0%</text><text x="${labW+axW}" y="12" text-anchor="end" class="axis">100%</text>`;
  html += `<line x1="${labW}" y1="18" x2="${labW+axW}" y2="18" stroke="#e2e0dc"/>`;
  MODELS.forEach((m, i) => {
    const h = DATA.honesty[m]; if (!h) return;
    const claimed = h.n ? h.claimed_yes/h.n : 0;
    const actual = (() => { const [ok, n] = cell(m, "probe", "ALL"); return n ? ok/n : 0; })();
    const y = 40 + i*rowH;
    const x1 = labW + claimed*axW, x2 = labW + actual*axW;
    html += `<text x="${labW-8}" y="${y+4}" text-anchor="end" class="dim">${ML[m]}</text>`;
    html += `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#c9c5be" stroke-width="2"/>`;
    html += `<circle cx="${x1}" cy="${y}" r="6" fill="#c8860d"/><circle cx="${x2}" cy="${y}" r="6" fill="#2c4a6b"/>`;
    if (i === 0){
      html += `<text x="${x1}" y="${y-12}" text-anchor="middle" fill="#c8860d">says it can</text>`;
      html += `<text x="${x2}" y="${y+22}" text-anchor="middle" fill="#2c4a6b">actually right</text>`;
    }
  });
  html += "</svg>";
  $("#chart2").innerHTML = html;
  const gaps = MODELS.filter(m=>DATA.honesty[m]).map(m => {
    const h = DATA.honesty[m], claimed = h.n ? h.claimed_yes/h.n : 0;
    const [ok, n] = cell(m, "probe", "ALL");
    return [m, Math.round(100*(claimed - (n?ok/n:0)))];
  }).sort((a,b)=>b[1]-a[1]);
  const over = gaps.filter(g=>g[1]>5).length, under = gaps.filter(g=>g[1]<-5).length;
  $("#cap2-take").textContent = `no model's dots meet: ${over} claim far more than they deliver (widest gap ${ML[gaps[0][0]]}, ${gaps[0][1]} points) and ${under} deny ability they have (${ML[gaps[gaps.length-1][0]]}, ${Math.abs(gaps[gaps.length-1][1])} points the other way).`;

  $("#honesty-rows").innerHTML = MODELS.filter(m=>DATA.honesty[m]).map(m => {
    const h = DATA.honesty[m];
    const rate = h.claimed_yes ? Math.round(100*h.claimed_yes_wrong/h.claimed_yes) : 0;
    return `<tr data-m="${m}" style="cursor:pointer"><td>${ML[m]}</td>
      <td class="num">${h.claimed_yes} / ${h.n}</td><td class="num">${h.claimed_yes_wrong}</td>
      <td class="num ${rate>=50?'bad':''}">${h.claimed_yes?rate+"%":"n/a"}</td></tr>`;
  }).join("");
  function showExamples(m){
    const ex = [];
    for (const t of DATA.tasks){
      const e = t.runs[m+"|probe"];
      if (e && e.claim && !e.ok) ex.push({t, e});
      if (ex.length >= 3) break;
    }
    $("#sure-examples").innerHTML = ex.length ? ex.map(({t,e}) =>
      `<div class="turn model"><span class="who">${ML[m]} · said yes · task ${t.id}</span>` +
      `answered <b>${escapeHtml(e.pred||"(nothing parseable)")}</b>, correct answer ${escapeHtml(t.truth)}</div>`).join("")
      : `<div class="turn model"><span class="who">${ML[m]}</span>no wrong-while-sure rows for this model.</div>`;
  }
  document.querySelectorAll("#honesty-rows tr").forEach(r => r.onclick = () => showExamples(r.dataset.m));
  showExamples(gaps[0][0]);
  const worstH = MODELS.filter(m=>DATA.honesty[m]).map(m=>{const h=DATA.honesty[m];return [m,h.claimed_yes_wrong,h.claimed_yes];}).sort((a,b)=>b[1]-a[1])[0];
  const humble = MODELS.filter(m=>DATA.honesty[m]).sort((a,b)=>DATA.honesty[a].claimed_yes-DATA.honesty[b].claimed_yes)[0];
  $("#verdict2").innerHTML = `<b>Self-assessment is broken in both directions.</b>
    ${ML[worstH[0]]} claimed it could answer ${worstH[2]} of the 120 tasks and was wrong on ${worstH[1]} of those claims${worstH[0]==="mimir" ? ", the same shape as its 382-of-521 result on DAISY" : ""}. ${ML[humble]} is the mirror image: it claimed ability ${DATA.honesty[humble].claimed_yes} times in 120
    while actually scoring ${pct(...cell(humble,"probe","ALL"))} percent.
    Neither the boaster nor the denier can be used as its own gatekeeper, which is the design argument for the next act.`;
})();

/* ---------- act 3: dumbbell unaided -> agent, behaviour, transcripts ---------- */
(function(){
  const W = 560, rowH = 40, labW = 110, axW = 380;
  let html = `<svg width="${W}" height="${MODELS.length*rowH+46}" viewBox="0 0 ${W} ${MODELS.length*rowH+46}">`;
  html += `<text x="${labW}" y="12" class="axis">0%</text><text x="${labW+axW}" y="12" text-anchor="end" class="axis">100%</text>`;
  html += `<line x1="${labW}" y1="18" x2="${labW+axW}" y2="18" stroke="#e2e0dc"/>`;
  MODELS.forEach((m, i) => {
    const u = pct(...cell(m,"unaided","ALL"))/100, a = pct(...cell(m,"agent","ALL"))/100;
    const y = 40 + i*rowH, x1 = labW + u*axW, x2 = labW + a*axW;
    html += `<text x="${labW-8}" y="${y+4}" text-anchor="end" class="dim">${ML[m]}</text>`;
    html += `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#c9c5be" stroke-width="2"/>`;
    html += `<circle cx="${x1}" cy="${y}" r="6" fill="#8b95a1"/><circle cx="${x2}" cy="${y}" r="6" fill="#2f7d54"/>`;
    html += `<text x="${Math.max(x1,x2)+10}" y="${y+4}">${Math.round(u*100)} to ${Math.round(a*100)}</text>`;
    if (i === 0){
      html += `<text x="${x1}" y="${y-12}" text-anchor="middle" fill="#8b95a1">unaided</text>`;
      html += `<text x="${x2}" y="${y+22}" text-anchor="middle" fill="#2f7d54">with tools</text>`;
    }
  });
  html += "</svg>";
  $("#chart3").innerHTML = html;
  const deltas = MODELS.map(m => [m, pct(...cell(m,"agent","ALL")) - pct(...cell(m,"unaided","ALL"))]).sort((a,b)=>b[1]-a[1]);
  const nonUsers = MODELS.filter(m => DATA.agent[m] && DATA.agent[m].used_tool <= 5);
  $("#cap3-take").textContent = `the gain tracks protocol competence, not size: ${ML[deltas[0][0]]} used tools on ${DATA.agent[deltas[0][0]].used_tool} of 120 tasks and gained ${deltas[0][1] > 0 ? "+" + deltas[0][1] : deltas[0][1]} points, while ${nonUsers.map(m=>ML[m]).join(" and ") || "no model"} barely attempted a call and moved nowhere.`;

  $("#behav-rows").innerHTML = MODELS.filter(m=>DATA.agent[m]).map(m => {
    const s = DATA.agent[m];
    return `<tr><td>${ML[m]}</td><td class="num">${s.used_tool} / ${s.rows}</td>
      <td class="num">${s.tool_calls}</td><td class="num">${s.malformed}</td><td class="num">${s.no_answer}</td></tr>`;
  }).join("");

  /* transcript viewer */
  let trModel = deltas[0][0], trIdx = 0;
  const trTasks = m => DATA.tasks.filter(t => { const e=t.runs[m+"|agent"]; return e && e.tr && e.tr.length > 1; });
  function renderTrChips(){
    $("#trmodels").innerHTML = MODELS.map(m =>
      `<button class="chip ${m===trModel?'on':''}" data-m="${m}">${ML[m]}</button>`).join("");
    document.querySelectorAll("#trmodels .chip").forEach(b =>
      b.onclick = () => { trModel = b.dataset.m; trIdx = 0; renderTr(); });
  }
  function renderTr(){
    renderTrChips();
    const list = trTasks(trModel);
    if (!list.length){ $("#transcript").innerHTML = `<div class="turn model">no multi-turn transcripts for this model.</div>`; $("#trpos").textContent = ""; return; }
    trIdx = ((trIdx % list.length) + list.length) % list.length;
    const t = list[trIdx], e = t.runs[trModel+"|agent"];
    $("#trpos").textContent = `${t.id} · ${e.ok ? "ended right" : "ended wrong"} · ${trIdx+1} of ${list.length}`;
    $("#transcript").innerHTML =
      `<div class="turn tool"><span class="who">task</span>${escapeHtml(t.q.split("\n\n").slice(-1)[0])}</div>` +
      e.tr.map(s => `<div class="turn ${s.who}"><span class="who">${s.who === "model" ? ML[trModel] : "tool"}</span>${escapeHtml(s.text)}</div>`).join("") +
      `<div class="turn tool"><span class="who">verdict</span>${e.ok ? "right" : "wrong"}; computed answer ${escapeHtml(t.truth)}</div>`;
  }
  $("#trprev").onclick = () => { trIdx--; renderTr(); };
  $("#trnext").onclick = () => { trIdx++; renderTr(); };
  renderTr();

  const top = deltas[0];
  const topAgent = DATA.agent[top[0]] || {};
  // accuracy among tasks where the top model actually produced an answer
  let ansOk = 0, ansN = 0;
  for (const t of DATA.tasks){
    const e = t.runs[top[0]+"|agent"];
    if (e && e.pred){ ansN++; if (e.ok) ansOk++; }
  }
  $("#verdict3").innerHTML = `<b>Tools help exactly as far as the model can drive them.</b>
    ${ML[top[0]]} gains ${top[1] > 0 ? "+" + top[1] : top[1]} points overall, and on the tasks where it actually finished it was right ${pct(ansOk, ansN)} percent of the time;
    the rest died inside the call protocol (${topAgent.malformed || 0} malformed calls, ${topAgent.no_answer || 0} tasks with no answer at all).
    Two models never really attempted the protocol and gained nothing. The sharpest lesson sits in the clade column:
    a model that drops one argument and gets an unhelpful error back can end up below its own unaided score.
    That finding does not dangle; the remedy is measured directly below.`;
})();

/* ---------- remedy arm: agent vs agent2 ---------- */
(function(){
  const have = MODELS.some(m => DATA.table[m+"|agent2"]);
  if (!have){ const r = $("#remedy"); if (r) r.hidden = true; return; }
  $("#remedy-rows").innerHTML = MODELS.map(m => {
    const a = pct(...cell(m,"agent","ALL")), b = pct(...cell(m,"agent2","ALL")), d = b - a;
    return `<tr><td>${ML[m]}</td><td class="num">${a}%</td><td class="num">${b}%</td>
      <td class="num ${d>0?'ok':d<0?'bad':''}">${d>0?"+":""}${d}</td></tr>`;
  }).join("");
  const gains = MODELS.map(m => [m, pct(...cell(m,"agent2","ALL")) - pct(...cell(m,"agent","ALL"))]).sort((a,b)=>b[1]-a[1]);
  const cladeTop = gains[0][0];
  const cladeBefore = pct(...cell(cladeTop,"agent","clade")), cladeAfter = pct(...cell(cladeTop,"agent2","clade"));
  $("#capR-take").textContent = `error messages are part of the interface: the biggest mover is ${ML[gains[0][0]]} at ${gains[0][1]>0?"+"+gains[0][1]:gains[0][1]} points overall (clade kind: ${cladeBefore} to ${cladeAfter} percent), from changing nothing but the text of the error.`;
})();

/* ---------- guided tour: placement from document coordinates ---------- */
(function(){
  const STEPS = [
    {sel:"header h1", k:"Welcome · 1 of 8", html:`This page asks one question: <b>can a small language model be trusted around phylogenetic trees?</b> Not to build them, but to read them, know its limits, and drive the software that does the real work. Three acts, five models, 120 tasks, every answer logged.`},
    {sel:"#domainfig", k:"The domain · 2 of 8", html:`One tree, three forms: drawing, Newick text, phylo2vec vector. The models only ever see text. If these three forms make sense, the whole page does; the glossary below stays open for the rest.`},
    {sel:"#browser", k:"The tasks · 3 of 8", html:`<b>Click a task kind, then Next task.</b> Each card shows one real question, the computed correct answer, and what all five models actually said unaided. The wrong answers are worth reading; they fail in confident, specific ways.`},
    {sel:"#chart1", k:"Act 1 result · 4 of 8", html:`Unaided accuracy by task kind. Counting taxa is already shaky; expanding a phylo2vec vector is near zero everywhere. That is the floor this page stands on.`},
    {sel:"#chart2", k:"Act 2 · 5 of 8", html:`Before answering, each model was asked: can you do this without tools, yes or no? Amber dot: how often it said yes. Blue dot: how often it was actually right. The gap is overconfidence, and it repeats the DAISY finding on a new domain.`},
    {sel:"#chart3", k:"Act 3 · 6 of 8", html:`The same models, given the phylo2vec library as six tools. Grey dot to green dot is what the library added. The models that can follow a simple call protocol jump; the ones that cannot, do not.`},
    {sel:"#transcript", k:"Real transcripts · 7 of 8", html:`<b>Pick a model and step through.</b> These are unedited logged agent runs: the tool calls the model wrote, the results it got back, and where it stopped. Both the clean runs and the failures are here.`},
    {sel:"#fails h2", k:"Limits · 8 of 8", html:`What this page does not show, stated before you find it: synthetic small trees, one run, one agent protocol, and one model out of its language. The coda has the method and the one-line command that reruns everything. Explore freely; this button restarts the tour.`},
  ];
  const root = $("#tour"), hl = $("#tour-hl"), card = $("#tour-card");
  let idx = 0;
  function place(){
    const st = STEPS[idx];
    const elm = document.querySelector(st.sel);
    if (!elm){ next(); return; }
    const r = elm.getBoundingClientRect();
    const top = r.top + window.scrollY, left = r.left + window.scrollX;
    root.style.height = document.documentElement.scrollHeight + "px";
    hl.style.left = (left-8)+"px"; hl.style.top = (top-8)+"px";
    hl.style.width = (r.width+16)+"px"; hl.style.height = (r.height+16)+"px";
    const dots = STEPS.map((_,i)=>`<i class="${i===idx?'on':''}"></i>`).join("");
    card.innerHTML = `<div class="tk">${st.k}</div><p>${st.html}</p>
      <div class="tour-nav"><div class="dots">${dots}</div>
      ${idx>0?'<button class="tour-btn" id="tprev">Back</button>':""}
      <button class="tour-btn" id="tskip">Close</button>
      <button class="tour-btn primary" id="tnext">${idx<STEPS.length-1?"Next":"Done"}</button></div>`;
    const cw = Math.min(400, innerWidth-32);
    let cx = left + r.width + 18, cy = top;
    if (cx + cw > window.scrollX + document.documentElement.clientWidth - 16){ cx = Math.max(16, left); cy = top + r.height + 14; }
    card.style.left = cx+"px"; card.style.top = cy+"px";
    window.scrollTo({top: Math.max(0, top - 120), behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth"});
    $("#tnext").onclick = next; $("#tskip").onclick = stop;
    const p = $("#tprev"); if (p) p.onclick = () => { idx = Math.max(0, idx-1); place(); };
  }
  function next(){ if (idx >= STEPS.length-1){ stop(); return; } idx++; place(); }
  function stop(){ root.classList.remove("on"); try{ localStorage.setItem("pad_tour","done"); }catch(e){} }
  function start(){ idx = 0; root.classList.add("on"); place(); }
  $("#tourbtn").addEventListener("click", start);
  let seen = null; try{ seen = localStorage.getItem("pad_tour"); }catch(e){}
  if (!seen) setTimeout(start, 700);
})();
})();
